<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();$students=(int)db()->query('SELECT COUNT(*) FROM users WHERE role="student"')->fetchColumn();$active=(int)db()->query('SELECT COUNT(*) FROM users WHERE role="student" AND status="active"')->fetchColumn();$tx=(int)db()->query('SELECT COUNT(*) FROM transactions WHERE status="active"')->fetchColumn();$cats=(int)db()->query('SELECT COUNT(*) FROM categories WHERE is_active=1')->fetchColumn();$top=db()->query('SELECT c.name,COUNT(t.transaction_id) total FROM transactions t JOIN categories c ON c.category_id=t.category_id WHERE t.status="active" GROUP BY c.category_id,c.name ORDER BY total DESC LIMIT 8')->fetchAll();$pageTitle='Admin Dashboard';$activePage='dashboard';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow"><i></i> CONTROL CENTER</span><h1>Campus Coin system</h1><p>Monitor users, activity and system content.</p></div></section><div class="stats-grid"><div class="stat-card highlight"><span>Students</span><strong><?=$students?></strong><small><?=$active?> active</small></div><div class="stat-card"><span>Transactions</span><strong><?=$tx?></strong><small>active records</small></div><div class="stat-card"><span>Categories</span><strong><?=$cats?></strong><small>system + personal</small></div><div class="stat-card"><span>Database</span><strong>Online</strong><small>PDO connection ready</small></div></div><div class="two-column"><section class="panel"><div class="panel-head"><div><span class="panel-kicker">USAGE</span><h2>Most used categories</h2></div></div><?php foreach($top as$r):?><div class="rank-row"><span><?=e($r['name'])?></span><b><?=$r['total']?></b></div><?php endforeach;?></section><section class="panel"><div class="panel-head"><div><span class="panel-kicker">ADMIN TOOLS</span><h2>Quick access</h2></div></div><div class="tip-grid"><a class="saved-card" href="<?=e(url('admin/users.php'))?>"><strong>User management</strong><p>View and control student accounts.</p></a><a class="saved-card" href="<?=e(url('admin/categories.php'))?>"><strong>Categories</strong><p>Manage system defaults.</p></a><a class="saved-card" href="<?=e(url('admin/analytics.php'))?>"><strong>Analytics</strong><p>Usage trends and category data.</p></a><a class="saved-card" href="<?=e(url('admin/announcements.php'))?>"><strong>Announcements</strong><p>Publish system messages.</p></a></div></section></div><?php require __DIR__.'/../includes/footer.php';?>